import{_ as t,o as r,c as i,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2018-10-23 :: Ceph Code walk-through: Consistency with OSD Peering","description":"","frontmatter":{"title":"2018-10-23 :: Ceph Code walk-through: Consistency with OSD Peering","date":"2018-10-23T00:00:00.000Z","updated":"2018-11-03T00:00:00.000Z","tags":["Ceph","Peering Process","OSD","Consistency","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/2018-10-23_-_-_Ceph_Code_walk-through_-_Consistency_with_OSD_Peering.md","filePath":"posts/2018/2018-10-23_-_-_Ceph_Code_walk-through_-_Consistency_with_OSD_Peering.md","lastUpdated":1780460162000}'),o={name:"posts/2018/2018-10-23_-_-_Ceph_Code_walk-through_-_Consistency_with_OSD_Peering.md"};function s(l,e,g,_,a,p){return r(),i("div",null,[...e[0]||(e[0]=[n("<p>会议纪要：</p><p><strong>会议主题</strong>： Ceph分布式存储系统中OSD对等状态同步（Peering）过程的代码讲解</p><p><strong>会议时间</strong>： 2018年10月23日</p><p><strong>参会人员</strong>： Brad（主讲人）、Tim（提问者）及其他未具名参与者</p><p><strong>会议内容</strong>：</p><ul><li><strong>Peering过程概述</strong>： Peering是一个同步所有OSD关于数据对象状态和元数据的过程，主要由主OSD驱动，通过Boost State Chart库实现的状态机来管理。该过程主要发生在PGH（Placement Group Header）和PGCC（Placement Group Cache）中。</li><li><strong>Peering状态机</strong>： <ul><li>使用Boost State Chart库实现，嵌入在HPG（Heap）中。</li><li>包含多个状态，如初始状态、重置状态、启动状态、主状态、对等状态等。</li><li>状态转换由事件触发，例如激活事件、初始化事件、获取信息事件、获取日志事件等。</li></ul></li><li><strong>Peering关键步骤</strong>： <ul><li><strong>获取信息</strong>： 向其他OSD查询PG信息T结构，包括版本号、最后完成时间、最后启动时间等。</li><li><strong>选择活动集</strong>： 根据获取的信息，选择最佳的活动集。</li><li><strong>获取日志</strong>： 从其他OSD获取权威日志。</li><li><strong>处理主日志</strong>： 将权威日志与本地日志合并。</li><li><strong>获取缺失数据</strong>： 请求缺失数据集和完整日志。</li><li><strong>激活</strong>： 创建激活事件，将状态机切换到活动状态。</li><li><strong>确认激活</strong>： 所有副本激活并确认后，更新PG信息T结构中的历史记录。</li><li><strong>恢复</strong>： 根据需要执行恢复操作，例如回填和日志处理。</li></ul></li><li><strong>会议讨论要点</strong>： <ul><li>重点讨论了Peering过程中的状态机实现、状态转换、事件处理等关键细节。</li><li>讨论了选择权威日志、处理缺失数据、确认激活等关键步骤。</li><li>讨论了Peering过程中的错误处理和异常情况。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>Brad将提供相关文档和代码链接，方便参会者进一步学习和研究。</li><li>参会者可以在邮件、IRC等渠道向Brad提问，继续讨论Peering过程。</li></ul></li></ul><p><strong>会议总结</strong>：</p><p>本次会议深入讨论了Ceph分布式存储系统中OSD对等状态同步（Peering）过程，对Peering状态机、关键步骤和实现细节进行了详细讲解。会议内容有助于参会者更好地理解Peering过程，并为后续的开发和维护工作提供参考。</p>",8)])])}const P=t(o,[["render",s]]);export{C as __pageData,P as default};
